package org.jlinalg.genetics;

import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import java.util.Random;
import org.junit.jupiter.api.Test;

class HaplotypeDosageTest {
    @Test void haploidBernoulliMoments() {var p=HaplotypeDosage.posterior(.25);assertEquals(List.of(.75,.25),p.genotypeProbabilities());assertEquals(.25,p.dosage());assertEquals(.1875,p.variance());assertEquals(List.of(0),p.phasedCalls());assertEquals(1,p.ploidy());}
    @Test void diploidRationalMoments() {var p=HaplotypeDosage.posterior(.25,.75);assertEquals(List.of(.1875,.625,.1875),p.genotypeProbabilities());assertEquals(1,p.dosage());assertEquals(.375,p.variance());assertEquals(List.of(0,1),p.phasedCalls());assertEquals(2,p.ploidy());}
    @Test void certainHeterozygoteRetainsPhase() {var p=HaplotypeDosage.posterior(1,0);assertEquals(List.of(0.,1.,0.),p.genotypeProbabilities());assertEquals(List.of(1,0),p.phasedCalls());assertEquals(0,p.variance());}
    @Test void halfProbabilityCallsAlt() {assertEquals(List.of(1),HaplotypeDosage.posterior(.5).phasedCalls());assertEquals(List.of(1,1),HaplotypeDosage.posterior(.5,.5).phasedCalls());}
    @Test void perCopyCallsNeedNotMaximizeGenotypeProbability() {var p=HaplotypeDosage.posterior(.4,.4);assertEquals(List.of(0,0),p.phasedCalls());assertTrue(p.genotypeProbabilities().get(1)>p.genotypeProbabilities().get(0));assertEquals(.48,p.genotypeProbabilities().get(1),1e-15);}
    @Test void swappingCopiesChangesPhaseOnly() {var a=HaplotypeDosage.posterior(.1,.8);var b=HaplotypeDosage.posterior(.8,.1);assertEquals(a.genotypeProbabilities(),b.genotypeProbabilities());assertEquals(a.dosage(),b.dosage());assertEquals(a.variance(),b.variance());assertEquals(List.of(0,1),a.phasedCalls());assertEquals(List.of(1,0),b.phasedCalls());}
    @Test void genotypeProbabilityMomentsAgreeWithCopyMoments() {var rng=new Random(91827);for(int i=0;i<1000;i++){var p=HaplotypeDosage.posterior(rng.nextDouble(),rng.nextDouble());var g=p.genotypeProbabilities();double mean=g.get(1)+2*g.get(2),second=g.get(1)+4*g.get(2);assertEquals(1,g.stream().mapToDouble(Double::doubleValue).sum(),1e-15);assertEquals(mean,p.dosage(),1e-15);assertEquals(second-mean*mean,p.variance(),2e-15);}}
    @Test void noInputCopiesRejected() {assertThrows(IllegalArgumentException.class,HaplotypeDosage::posterior);}
    @Test void absentCopiesRejected() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.posterior((double[])null));}
    @Test void polyploidInputIsNotSilentlyTruncated() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.posterior(.1,.2,.3));}
    @Test void nanIsNotMeanImputed() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.posterior(Double.NaN));}
    @Test void infiniteInputRejected() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.posterior(Double.POSITIVE_INFINITY));assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.posterior(Double.NEGATIVE_INFINITY));}
    @Test void outOfRangeInputsAreNotClipped() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.posterior(-1e-16));assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.posterior(Math.nextUp(1.)));}
    @Test void cohortKnownHaplotypeVarianceRatio() {var s=HaplotypeDosage.summarize(new double[][]{{.1,.2},{.8,.9}});assertEquals(2,s.samples());assertEquals(4,s.haplotypes());assertEquals(2,s.expectedAltCopies(),1e-15);assertEquals(.5,s.alleleFrequency(),1e-15);assertEquals(.5,s.estimatedHaplotypeR2().orElseThrow(),1e-15);assertEquals(.25,s.meanPosteriorVariance(),1e-15);assertEquals(.85,s.meanHaplotypeCallScore(),1e-15);}
    @Test void mixedPloidiesUseActualCopyDenominator() {var s=HaplotypeDosage.summarize(new double[][]{{.25},{.75,1}});assertEquals(3,s.haplotypes());assertEquals(2./3,s.alleleFrequency(),1e-15);assertEquals(1./3,s.minorAlleleFrequency(),1e-15);assertEquals(.1875,s.meanPosteriorVariance(),1e-15);}
    @Test void referenceMonomorphismIsUndefinedWithExplicitToolConvention() {var s=HaplotypeDosage.summarize(new double[][]{{0},{0,0}});assertEquals(0,s.alleleFrequency());assertTrue(s.estimatedHaplotypeR2().isEmpty());assertEquals(0,s.minimacR2Convention());assertEquals(1,s.meanHaplotypeCallScore());}
    @Test void alternateMonomorphismIsAlsoUndefined() {var s=HaplotypeDosage.summarize(new double[][]{{1},{1,1}});assertEquals(1,s.alleleFrequency());assertEquals(0,s.minorAlleleFrequency());assertTrue(s.estimatedHaplotypeR2().isEmpty());assertEquals(0,s.minimacR2Convention());}
    @Test void constantUncertainHaplotypesHaveZeroVarianceRatio() {var s=HaplotypeDosage.summarize(new double[][]{{.37,.37},{.37}});assertTrue(s.estimatedHaplotypeR2().isPresent());assertEquals(0,s.estimatedHaplotypeR2().orElseThrow());assertEquals(.37,s.alleleFrequency(),1e-15);}
    @Test void haplotypeRatioIsNotDiploidSampleVariance() {var s=HaplotypeDosage.summarize(new double[][]{{0,1}});assertEquals(1,s.estimatedHaplotypeR2().orElseThrow());assertEquals(1,s.expectedAltCopies());assertEquals(0,s.meanPosteriorVariance());}
    @Test void cohortOrderIsIrrelevantWithinDoubleRoundoff() {var a=HaplotypeDosage.summarize(new double[][]{{.001,.2},{.999},{.7,.4}});var b=HaplotypeDosage.summarize(new double[][]{{.4,.7},{.999},{.2,.001}});assertEquals(a.alleleFrequency(),b.alleleFrequency(),1e-15);assertEquals(a.estimatedHaplotypeR2().orElseThrow(),b.estimatedHaplotypeR2().orElseThrow(),1e-15);assertEquals(a.meanPosteriorVariance(),b.meanPosteriorVariance(),1e-15);}
    @Test void emptyOrAbsentCohortRejected() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.summarize(null));assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.summarize(new double[0][]));}
    @Test void absentOrEmptyRowsRequireExplicitHandling() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.summarize(new double[][]{null}));assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.summarize(new double[][]{{}}));}
    @Test void missingCohortCopyIsNotDiscarded() {assertThrows(IllegalArgumentException.class,()->HaplotypeDosage.summarize(new double[][]{{.1},{.2,Double.NaN}}));}
    @Test void alleleComplementReversesProbabilitiesAndPreservesVariance() {var a=HaplotypeDosage.posterior(.125,.75);var b=HaplotypeDosage.posterior(.875,.25);assertEquals(2-a.dosage(),b.dosage(),1e-15);assertEquals(a.variance(),b.variance());assertEquals(a.genotypeProbabilities().get(0),b.genotypeProbabilities().get(2));assertEquals(a.genotypeProbabilities().get(2),b.genotypeProbabilities().get(0));}
    @Test void probabilitiesNearLimitsStayFiniteAndBounded() {for(double p:new double[]{Double.MIN_VALUE,Math.nextUp(0.),Math.nextDown(1.),1.}){var x=HaplotypeDosage.posterior(p,p);assertTrue(Double.isFinite(x.variance())&&x.variance()>=0);assertTrue(x.genotypeProbabilities().stream().allMatch(v->Double.isFinite(v)&&v>=0&&v<=1));var s=HaplotypeDosage.summarize(new double[][]{{p}});assertTrue(s.estimatedHaplotypeR2().isEmpty()||s.estimatedHaplotypeR2().orElseThrow()>=0&&s.estimatedHaplotypeR2().orElseThrow()<=1);}}
    @Test void posteriorCollectionsAreImmutable() {var p=HaplotypeDosage.posterior(.2,.3);assertThrows(UnsupportedOperationException.class,()->p.genotypeProbabilities().set(0,0.));assertThrows(UnsupportedOperationException.class,()->p.phasedCalls().set(0,1));}
}
